export const F={tempo:8,energy:9,valence:10,danceability:11,acousticness:12,instrumentalness:13,speechiness:14,loudness:15,liveness:16};
export function normalize(s){return s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
export function search(tracks,query,limit=8){const q=normalize(query);if(!q)return [];const words=q.split(' ');return tracks.map(t=>{const title=normalize(t[1]),artist=normalize(t[2]),full=title+' '+artist;return {t,score:words.every(w=>full.includes(w))?(title===q?1000:title.startsWith(q)?500:artist===q?400:100)+t[4]/10:-1};}).filter(r=>r.score>=0).sort((a,b)=>b.score-a.score).slice(0,limit).map(r=>r.t);}
export function mood(t){if(t[F.valence]<.35&&t[F.energy]<.55)return 'Melancholic';if(t[F.energy]<.35)return 'Peaceful';if(t[F.valence]>.65&&t[F.energy]>.55)return 'Uplifting';if(t[F.energy]>.75)return 'Intense';return 'Dreamy';}
export function accepts(t,f={}){return (!f.minBpm||t[8]>=f.minBpm)&&(!f.maxBpm||t[8]<=f.maxBpm)&&(!f.voice||t[7]===f.voice)&&(!f.genre||t[6].includes(f.genre))&&(!f.mood||mood(t)===f.mood)&&(!f.clean||!t[5])&&(!f.acoustic||t[12]>=.65);}
export function recommend(tracks,seed,model,filters={},limit=24){const weights=model.weights,scale=model.scale;const seen=new Set([normalize(seed[1])+'|'+normalize(seed[2])]);const ranked=[];for(const t of tracks){if(t[0]===seed[0]||!accepts(t,filters))continue;if(filters.otherArtists&&normalize(t[2])===normalize(seed[2]))continue;let distance=0;for(let i=0;i<weights.length;i++){const d=(t[i+8]-seed[i+8])/scale[i];distance+=weights[i]*d*d;}ranked.push({track:t,distance});}ranked.sort((a,b)=>a.distance-b.distance);const result=[];const artistCounts=new Map();for(const r of ranked){const key=normalize(r.track[1])+'|'+normalize(r.track[2]);const artist=r.track[2];if(seen.has(key)||(artistCounts.get(artist)||0)>=2)continue;seen.add(key);artistCounts.set(artist,(artistCounts.get(artist)||0)+1);result.push(r);if(result.length>=limit)break;}return result;}
